insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-livlabs-pippa-starter-kit', 'Pippa Resistance Spring Starter Kit', 'Liv Labs', 'pelvic-floor', 'physical', 'The first wearable product designed to boost pelvic floor fitness, just by wearing it while you move, per Liv Labs. Pippa is a soft spring of platinum-catalyzed biomedical silicone, worn internally like a tampon; its spring-form gently engages the pelvic floor, creating continual light resistance that helps the brain better recruit the right muscles, at the right time, and with the right amount of force. Liv Labs'' comparison: a resistance band, but for the pelvic floor. The Starter Kit has one light-resistance spring (42 mm) and a reusable applicator, and is meant for women who have never had children and have been advised to do kegels. Developed over 7 years by female designers, engineers, athletes and clinical experts.', '$119.00', '/products/catalog/p-livlabs-pippa-starter-kit.webp', 'https://livlabsfitness.com/products/pippa-resistance-spring-starter-kit', '["fitness","pelvic-floor","comfort"]'::jsonb, '["pelvic-floor"]'::jsonb, '["livlabsfitness.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a fitness/wellness product, not a medical device, per Liv Labs (\"not intended to diagnose, treat, cure, or prevent any disease\"). ayna found no FDA 510(k) clearance or FDA registration for Liv Labs or Pippa (openFDA, checked 2026-10-29). Its NIH grant was awarded for testing toward a 510(k) clearance, which has not been found.","materials":"Starter Kit: one light-resistance (42 mm) spring and one reusable applicator. Springs are made in the USA of premium, platinum-catalyzed biomedical silicone, free of BPAs and microplastics, per Liv Labs. Each spring is safe for up to 92 uses if used as directed, per Liv Labs.","recalls":"No recalls found.","sideEffects":"Liv Labs says Pippa has been safety-tested, including for use during pregnancy and menstruation. One Starter Kit reviewer said wearing it every day almost gave her sore pelvic floor muscles, and switched to about three times a week.","opinionAlerts":"It is worn internally, so follow the cleaning steps every time (wash with a cleanser and air dry between uses). If you can feel it during use and can''t insert it further, Liv Labs suggests seeing a healthcare provider."}'::jsonb, 'Liv Labs funded a mechanistic study at Baylor University''s Institute for Musculoskeletal Advancement, led by Dr. Laurel Proulx, a pelvic health physical therapist and researcher. Its abstract was published by the International Continence Society (ICS 2026, abstract 105). Fifteen women aged 20 to 39 with no pelvic floor symptoms were imaged with and without Pippa inserted (ultrasound and shear wave elastography), in a single group, before-and-after design. With Pippa in place, normal lifting and lowering of the pelvic floor was unchanged, and the puborectalis muscle became stiffer from rest to bearing down (change-score analysis, p=0.03). During a voluntary squeeze, stiffness was lower with the device (p=0.04), which the authors say is not well understood. The study measured muscle mechanics in one session, not symptoms; the authors say research in women with symptoms, during and after pregnancy, and in perimenopause is needed to know whether it helps. The abstract states the funder had no role in the design, analysis or writing.

Dr. Mallory Willis, a pelvic health physical therapist and owner of Peak Pelvic Health, wrote in a review on Liv Labs'' site: "These are a great, comfortable and easy to use option especially for postpartum recovery!"

For context, a related device category, weighted vaginal cones, has a Cochrane review: 23 small trials (1,806 women) found cones better than no treatment for stress urinary incontinence and about as good as pelvic floor muscle training. Cones work differently (holding a weight in place), so this doesn''t test Pippa itself.', 'On livlabsfitness.com the Starter Kit has 2 reviews, both 5 stars (checked October 29, 2026). One reviewer found daily wear almost made her muscles sore and now wears it about three times a week; another, using it to stay ahead of problems as she ages, wears it on the treadmill and on walks and praised a customer-care call that walked her through insertion. The Fit Kit page has more reviews (13), most from women who have had children. Pippa was named a Fast Company 2025 Innovation by Design honoree, per Liv Labs.', 'A Liv Labs-funded mechanistic study in 15 women without symptoms (ICS 2026 abstract) found Pippa preserved normal pelvic floor movement and increased puborectalis stiffness during bearing down. It did not measure symptoms such as leaking, and no trial in women with symptoms has been published yet. Full results are expected in the journal Continence, per Liv Labs.', 'brand', 'From Liv Labs and the ICS 2026 abstract of a study Liv Labs funded, plus one independent review of a related device category (weighted vaginal cones).', 'curated', true, false, null, false, '{"idealCustomers":["Runners, power lifters, triathletes, Ironman competitors, gymnasts, dancers and other athletes","Postpartum moms who are very physically active","Women over 40 who are very physically active"],"brandNotes":"Liv Labs classes Pippa as a fitness/wellness product and ships it under the code for resistance bands. Brand disclaimer: \"This product is not intended to diagnose, treat, cure, or prevent any disease.\" Liv Labs is preparing Starter and Fit Kit versions that come with a storage pouch; images to follow.","doctorOpinionShort":"A Liv Labs-funded study of 15 women without symptoms (ICS 2026) found Pippa left normal pelvic floor movement unchanged and stiffened a key pelvic floor muscle during bearing down. It didn''t measure symptoms. A pelvic health PT calls it a comfortable, easy option for postpartum recovery.","doctorOpinionCitations":[{"url":"https://www.ics.org/2026/abstract/105","label":"ICS 2026 abstract 105: Neuromuscular effects of an OTC vaginal support device (Baylor University; funded by Liv Labs)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23836411/","label":"PubMed (NIH): Weighted vaginal cones for urinary incontinence (Cochrane review, 2013)"}],"whoItsFor":["Physically active women who want the benefits of pelvic floor exercise without a kegel routine: group classes, running, dancing, weight lifting, military training and sports (per Liv Labs)","Starter Kit: women who have never had children and have been advised to do kegels. If you''ve had children, Liv Labs recommends the Fit Kit.","Liv Labs'' three uses: worn during workouts for a passive pelvic floor boost; as a recovery tool for biofeedback and retraining after childbirth or injury; and for added resistance during pelvic floor exercises"],"howToUse":{"intro":"Per Liv Labs'' Quick Start Plan:","steps":["Insert it with the applicator, much like a tampon. A water-based lubricant can make insertion more comfortable.","Check placement: after a few moments you shouldn''t feel it. If you do, insert it further up. If that isn''t possible, consider seeing a healthcare provider.","Then move as usual: walk, hike, run, work out or do yard work. No squeeze-and-relax drills are needed, and kegels done with Pippa in place will feel harder.","Remove it any time. Wash with cleanser and air dry between uses. Each spring is good for up to 92 uses if used as directed."],"sourceUrl":"https://app.mypelvizen.com/marketplace_items/22","sourceLabel":"My Pelvizen: Pippa Resistance Spring (Liv Labs'' Quick Start Plan)"},"warnings":["Worn internally: wash it with a cleanser and air dry between every use (Liv Labs).","Not intended to diagnose, treat, cure or prevent any disease (Liv Labs). For leaking, prolapse or pelvic pain, see a clinician or pelvic floor physical therapist.","Pregnant or postpartum: Liv Labs says it''s safety-tested for use in pregnancy; check with your clinician first.","Stop and seek care for pain, bleeding, unusual discharge or signs of infection."],"ingredients":"Platinum-catalyzed biomedical silicone resistance spring (light, 42 mm); reusable applicator.","scientificCitations":[{"url":"https://www.ics.org/2026/abstract/105","text":"ICS 2026 abstract 105: Neuromuscular Effects of an Over-the-Counter Vaginal Support Device: A Mechanistic Evaluation in Asymptomatic Women","summary":"Single-group, before-and-after imaging study of 15 women aged 20 to 39 without symptoms (Baylor University). Pippa preserved normal pelvic floor movement and increased puborectalis stiffness during bearing down; stiffness during a voluntary squeeze was lower with the device. Funded by Liv Labs. Continence 19S (2026) 102582."},{"url":"https://pubmed.ncbi.nlm.nih.gov/23836411/","text":"Cochrane: Weighted vaginal cones for urinary incontinence (2013)","summary":"23 small trials, 1,806 women: cones were better than no treatment for stress urinary incontinence and about as good as pelvic floor muscle training. A related device category, not Pippa itself."}],"integrations":[],"badges":["Female-Founded","Fast Company 2025 Innovation by Design Honoree"],"verificationLinks":{"community":{"links":[{"platform":"website","url":"https://livlabsfitness.com/products/pippa-resistance-spring-starter-kit","text":"livlabsfitness.com: Pippa Starter Kit reviews","summary":"2 reviews, both 5 stars, as of October 29, 2026."},{"platform":"website","url":"https://app.mypelvizen.com/marketplace_items/22","text":"My Pelvizen: Pippa Resistance Spring","summary":"Liv Labs'' Quick Start Plan, quotes from users and a PT, and a summary of the research."},{"platform":"reddit","url":"https://www.reddit.com/r/pelvicfloor/search/?q=pippa%20liv%20labs","text":"Reddit r/pelvicfloor: Pippa/Liv Labs search","summary":"User discussion of the Pippa resistance spring."}]}},"isEmergingBrand":true,"imageSourceUrl":"https://livlabsfitness.com/products/pippa-resistance-spring-starter-kit","imageOriginalUrl":"https://cdn.shopify.com/s/files/1/0771/1087/0265/files/Starter_Kit_Pouch_Square.png?v=1764544146","imageVerifiedAt":"2026-09-26","imageReviewStatus":"verified-packaging"}'::jsonb),
  ('p-livlabs-pippa-fit-kit', 'Pippa Resistance Spring Fit Kit', 'Liv Labs', 'pelvic-floor', 'physical', 'The first wearable product designed to boost pelvic floor fitness, just by wearing it while you move, per Liv Labs. Pippa is a soft spring of platinum-catalyzed biomedical silicone, worn internally like a tampon; its spring-form gently engages the pelvic floor, creating continual light resistance that helps the brain better recruit the right muscles, at the right time, and with the right amount of force. The Fit Kit has two sizes, a light (42 mm) and a medium (50 mm) resistance spring, plus a reusable applicator, and is recommended for women who have had children and have been advised to do kegels. You may need to try both sizes to find your fit. Developed over 7 years by female designers, engineers, athletes and clinical experts.', '$149.00', '/products/catalog/p-livlabs-pippa-fit-kit.webp', 'https://livlabsfitness.com/products/pippa-fit-kit', '["fitness","pelvic-floor","postpartum","comfort"]'::jsonb, '["pelvic-floor"]'::jsonb, '["livlabsfitness.com","mypelvicbra.shop"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a fitness/wellness product, not a medical device, per Liv Labs (\"not intended to diagnose, treat, cure, or prevent any disease\"). ayna found no FDA 510(k) clearance or FDA registration for Liv Labs or Pippa (openFDA, checked 2026-10-29). Its NIH grant was awarded for testing toward a 510(k) clearance, which has not been found.","materials":"Fit Kit: one light (42 mm) and one medium (50 mm) resistance spring and one reusable applicator. Springs are made in the USA of premium, platinum-catalyzed biomedical silicone, free of BPAs and microplastics, per Liv Labs. Each spring is safe for up to 92 uses if used as directed, per Liv Labs.","recalls":"No recalls found.","sideEffects":"Liv Labs says Pippa has been safety-tested, including for use during pregnancy and menstruation. A Starter Kit reviewer said daily wear almost gave her sore pelvic floor muscles, and switched to about three times a week.","opinionAlerts":"It is worn internally, so follow the cleaning steps every time (wash with a cleanser and air dry between uses). If you can feel it during use and can''t insert it further, Liv Labs suggests seeing a healthcare provider."}'::jsonb, 'Liv Labs funded a mechanistic study at Baylor University''s Institute for Musculoskeletal Advancement, led by Dr. Laurel Proulx, a pelvic health physical therapist and researcher. Its abstract was published by the International Continence Society (ICS 2026, abstract 105). Fifteen women aged 20 to 39 with no pelvic floor symptoms were imaged with and without Pippa inserted (ultrasound and shear wave elastography), in a single group, before-and-after design. With Pippa in place, normal lifting and lowering of the pelvic floor was unchanged, and the puborectalis muscle became stiffer from rest to bearing down (change-score analysis, p=0.03). During a voluntary squeeze, stiffness was lower with the device (p=0.04), which the authors say is not well understood. The study measured muscle mechanics in one session, not symptoms; the authors say research in women with symptoms, during and after pregnancy, and in perimenopause is needed to know whether it helps. The abstract states the funder had no role in the design, analysis or writing.

Dr. Mallory Willis, a pelvic health physical therapist and owner of Peak Pelvic Health, wrote in a review of the Fit Kit on Liv Labs'' site: "These are a great, comfortable and easy to use option especially for postpartum recovery!"

For context, a related device category, weighted vaginal cones, has a Cochrane review: 23 small trials (1,806 women) found cones better than no treatment for stress urinary incontinence and about as good as pelvic floor muscle training. Cones work differently (holding a weight in place), so this doesn''t test Pippa itself.', 'On livlabsfitness.com the Fit Kit has 13 reviews: 11 five-star and 2 four-star (checked October 29, 2026). Several reviewers, many of them mothers, describe running, jumping classes and long runs without leaking, and one, years after a large vaginal birth, says she regained sensation and control within a week. Others note it''s comfortable, stays put and that you may need to try both sizes. On mypelvicbra.shop, its 2 reviews are both 2 stars; one says it would have worked better with flat ends. Pippa was named a Fast Company 2025 Innovation by Design honoree, per Liv Labs.', 'A Liv Labs-funded mechanistic study in 15 women without symptoms (ICS 2026 abstract) found Pippa preserved normal pelvic floor movement and increased puborectalis stiffness during bearing down. It did not measure symptoms such as leaking, and no trial in women with symptoms has been published yet. Full results are expected in the journal Continence, per Liv Labs.', 'brand', 'From Liv Labs and the ICS 2026 abstract of a study Liv Labs funded, plus one independent review of a related device category (weighted vaginal cones).', 'curated', true, false, null, false, '{"idealCustomers":["Runners, power lifters, triathletes, Ironman competitors, gymnasts, dancers and other athletes","Postpartum moms who are very physically active","Women over 40 who are very physically active"],"brandNotes":"Liv Labs classes Pippa as a fitness/wellness product and ships it under the code for resistance bands. Brand disclaimer: \"This product is not intended to diagnose, treat, cure, or prevent any disease.\" Liv Labs is preparing Starter and Fit Kit versions that come with a storage pouch; images to follow.","doctorOpinionShort":"A Liv Labs-funded study of 15 women without symptoms (ICS 2026) found Pippa left normal pelvic floor movement unchanged and stiffened a key pelvic floor muscle during bearing down. It didn''t measure symptoms. A pelvic health PT calls it a comfortable, easy option for postpartum recovery.","doctorOpinionCitations":[{"url":"https://www.ics.org/2026/abstract/105","label":"ICS 2026 abstract 105: Neuromuscular effects of an OTC vaginal support device (Baylor University; funded by Liv Labs)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23836411/","label":"PubMed (NIH): Weighted vaginal cones for urinary incontinence (Cochrane review, 2013)"}],"whoItsFor":["Physically active women who want the benefits of pelvic floor exercise without a kegel routine: group classes, running, dancing, weight lifting, military training and sports (per Liv Labs)","Fit Kit: women who have had children and have been advised to do kegels (Liv Labs'' recommendation)","Liv Labs'' three uses: worn during workouts for a passive pelvic floor boost; as a recovery tool for biofeedback and retraining after childbirth or injury; and for added resistance during pelvic floor exercises"],"howToUse":{"intro":"Per Liv Labs'' Quick Start Plan:","steps":["Insert it with the applicator, much like a tampon. A water-based lubricant can make insertion more comfortable.","Check placement: after a few moments you shouldn''t feel it. If you do, insert it further up. If that isn''t possible, consider seeing a healthcare provider.","Then move as usual: walk, hike, run, work out or do yard work. No squeeze-and-relax drills are needed, and kegels done with Pippa in place will feel harder.","Try both springs: Liv Labs suggests experimenting, or using each for different activities.","Remove it any time. Wash with cleanser and air dry between uses. Each spring is good for up to 92 uses if used as directed."],"sourceUrl":"https://app.mypelvizen.com/marketplace_items/22","sourceLabel":"My Pelvizen: Pippa Resistance Spring (Liv Labs'' Quick Start Plan)"},"warnings":["Worn internally: wash it with a cleanser and air dry between every use (Liv Labs).","Not intended to diagnose, treat, cure or prevent any disease (Liv Labs). For leaking, prolapse or pelvic pain, see a clinician or pelvic floor physical therapist.","Pregnant or postpartum: Liv Labs says it''s safety-tested for use in pregnancy; check with your clinician first.","Stop and seek care for pain, bleeding, unusual discharge or signs of infection.","Bought from myPelvicBra: products for internal use can''t be returned once the package is opened."],"ingredients":"Platinum-catalyzed biomedical silicone resistance springs (light 42 mm and medium 50 mm); reusable applicator.","scientificCitations":[{"url":"https://www.ics.org/2026/abstract/105","text":"ICS 2026 abstract 105: Neuromuscular Effects of an Over-the-Counter Vaginal Support Device: A Mechanistic Evaluation in Asymptomatic Women","summary":"Single-group, before-and-after imaging study of 15 women aged 20 to 39 without symptoms (Baylor University). Pippa preserved normal pelvic floor movement and increased puborectalis stiffness during bearing down; stiffness during a voluntary squeeze was lower with the device. Funded by Liv Labs. Continence 19S (2026) 102582."},{"url":"https://pubmed.ncbi.nlm.nih.gov/23836411/","text":"Cochrane: Weighted vaginal cones for urinary incontinence (2013)","summary":"23 small trials, 1,806 women: cones were better than no treatment for stress urinary incontinence and about as good as pelvic floor muscle training. A related device category, not Pippa itself."}],"integrations":[],"badges":["Female-Founded","Fast Company 2025 Innovation by Design Honoree"],"verificationLinks":{"community":{"links":[{"platform":"website","url":"https://livlabsfitness.com/products/pippa-fit-kit","text":"livlabsfitness.com: Pippa Fit Kit reviews","summary":"13 reviews (11 five-star, 2 four-star) as of October 29, 2026."},{"platform":"website","url":"https://www.mypelvicbra.shop/collections/all/products/pippa%C2%AE-resistance-spring","text":"mypelvicbra.shop: Pippa Resistance Spring","summary":"myPelvicBra''s listing of the Fit Kit, with 2 reviews (both 2 stars) as of October 29, 2026."},{"platform":"website","url":"https://app.mypelvizen.com/marketplace_items/22","text":"My Pelvizen: Pippa Resistance Spring","summary":"Liv Labs'' Quick Start Plan, quotes from users and a PT, and a summary of the research."}]}},"isEmergingBrand":true,"imageSourceUrl":"https://livlabsfitness.com/products/pippa-fit-kit","imageOriginalUrl":"https://cdn.shopify.com/s/files/1/0771/1087/0265/files/Fit_Kit_Pouch_on_Square.png?v=1764545785","imageVerifiedAt":"2026-09-26","imageReviewStatus":"verified-packaging"}'::jsonb)
